 "content": "from collections import deque

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 5 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            component = []
            while q:
                y, x = q.popleft()
                component.append((y, x))
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == 5 and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            r0 = min(y for y, _ in component)
            r1 = max(y for y, _ in component)
            c0 = min(x for _, x in component)
            c1 = max(x for _, x in component)
            for y in range(r0, r1 + 1):
                for x in range(c0, c1 + 1):
                    if out[y][x] == 0:
                        out[y][x] = 2
            if r0 > 0:
                for x in range(c1):
                    if out[r0 - 1][x] == 0:
                        out[r0 - 1][x] = 2
    return out

if __name__ == '__main__':
    demo = [[0]*10 for _ in range(10)]
    shape = [[5,5,0,5],[5,0,0,5],[5,0,0,5],[5,5,5,5]]
